import {retrieve,explain,itinerary,categories} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const origins={baiterek:{lat:51.1283,lon:71.4304},expo:{lat:51.0884,lon:71.4077},botanical:{lat:51.1055,lon:71.4234},museum:{lat:51.1185,lon:71.4693},river:{lat:51.1655,lon:71.4228}};
const icons={cafe:'☕',park:'♧',museum:'▥',landmark:'⌂',mall:'◇',playground:'☀'};let dataset,category='all',origin=origins.baiterek,lastResult,selected=[],map,markers=[],line,originMarker,searchVersion=0;
if(window.L){map=L.map('map',{zoomControl:false}).setView([origin.lat,origin.lon],14);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);}else $('#map').innerHTML='<div class="fallback-map">Карта недоступна. Все рекомендации, расстояния и ссылки на места работают ниже.</div>';
function drawMap(){if(!map)return;markers.forEach(m=>map.removeLayer(m));markers=[];if(originMarker)map.removeLayer(originMarker);originMarker=L.marker([origin.lat,origin.lon],{icon:L.divIcon({className:'origin-pin',iconSize:[15,15]})}).addTo(map).bindPopup('Ваша отправная точка');(lastResult?.results||[]).forEach((p,i)=>markers.push(L.marker([p.lat,p.lon],{icon:L.divIcon({className:'pin',html:String(i+1),iconSize:[33,33],iconAnchor:[16,16]})}).addTo(map).bindPopup(`<b>${esc(p.name)}</b><br>≈ ${p.walk} мин пешком`)));const points=[[origin.lat,origin.lon],...(lastResult?.results||[]).map(p=>[p.lat,p.lon])];map.fitBounds(points,{padding:[50,50],maxZoom:15});}
function options(){return {origin,minutes:+$('#minutes').value,radius:+$('#radius').value,query:$('#query').value,category,indoor:$('#indoor').checked,accessible:$('#accessible').checked,night:$('#night').checked};}
function card(p,i){const e=explain(p,$('#query').value),isAdded=selected.some(x=>x.id===p.id);return `<article class="result-card"><div class="place-art ${esc(p.category)}"><span class="rank">${i+1}</span>${icons[p.category]||'⌖'}</div><div><div class="card-top"><div><h3>${esc(p.name)}</h3><div class="meta">${esc(categories[p.category]||p.category)} · ${p.km<1?Math.round(p.km*1000)+' м':p.km.toFixed(1)+' км'} по прямой · ≈ ${p.walk} мин пешком</div></div><button class="add ${isAdded?'added':''}" data-add="${esc(p.id)}" aria-label="${isAdded?'Убрать':'Добавить'} ${esc(p.name)} в маршрут">${isAdded?'✓':'+'}</button></div><p class="reason"><b>Почему:</b> ${esc(e.why)}</p><p class="action"><b>Идея · ${p.visit} мин:</b> ${esc(e.action)}</p><div class="uncertain"><span>◷ ${esc(e.uncertainty)}</span><a href="${esc(p.source)}" target="_blank" rel="noreferrer">Данные OSM ↗</a></div></div></article>`;}
function renderCards(){ $('#results').innerHTML=lastResult.results.length?lastResult.results.map(card).join(''):'<div class="empty"><b>Под ваши условия мест не найдено.</b><br>Увеличьте время или радиус, измените категорию либо снимите строгий фильтр доступности. Мы не заменяем отсутствующие данные выдуманными местами.</div>';$('#results').setAttribute('aria-busy','false');document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const p=lastResult.results.find(x=>x.id===b.dataset.add);selected=selected.some(x=>x.id===p.id)?selected.filter(x=>x.id!==p.id):[...selected,p];renderCards();renderRoute();});}
function renderRoute(){const panel=$('#routePanel');if(line&&map){map.removeLayer(line);line=null;}if(!selected.length){panel.hidden=true;return;}const route=itinerary(selected,origin,+$('#minutes').value);panel.hidden=false;const skipped=selected.length-route.stops.length;panel.innerHTML=`<h3>Ваш маленький маршрут · ${route.total} мин</h3><p>${route.stops.map((p,i)=>`${i+1}. ${esc(p.name)} <small>≈ ${p.legWalk} мин в пути + ${p.visit} мин на месте</small>`).join('<br>')||'Выбранные остановки не помещаются в бюджет времени.'}</p>${skipped?`<small>${skipped} остановка(и) не включены: не хватает времени.</small><br>`:''}<small>Без обратного пути. Линии на карте — схема, не пешеходная навигация.</small><br>${route.stops.length?'<a id="externalRoute" target="_blank" rel="noreferrer">Открыть маршрут ↗</a><button id="downloadRoute">Скачать план ↓</button>':''}<button id="clearRoute">Очистить</button>`;$('#clearRoute').onclick=()=>{selected=[];renderCards();renderRoute();};if(route.stops.length){const last=route.stops.at(-1),url=new URL('https://www.google.com/maps/dir/');url.search=new URLSearchParams({api:'1',origin:`${origin.lat},${origin.lon}`,destination:`${last.lat},${last.lon}`,travelmode:'walking',...(route.stops.length>1?{waypoints:route.stops.slice(0,-1).map(p=>`${p.lat},${p.lon}`).join('|')}: {})}).toString();$('#externalRoute').href=url.toString();$('#downloadRoute').onclick=()=>{const blob=new Blob([`QADAM · Астана\nОценка: ${route.total} мин, без обратного пути.\n\n`+route.stops.map((p,i)=>`${i+1}. ${p.name}\nПешком ≈ ${p.legWalk} мин; посещение ${p.visit} мин.\n${explain(p).action}\nИсточник: ${p.source}\nЧасы: ${p.openingHours||'неизвестны'}\n`).join('\n')],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='qadam-walk.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};if(map)line=L.polyline([[origin.lat,origin.lon],...route.stops.map(p=>[p.lat,p.lon])],{color:'#203c2d',weight:3,dashArray:'7 9'}).addTo(map);}}
async function search(){if(!dataset)return;const version=++searchVersion;selected=[];const o=options();lastResult=retrieve(dataset.pois,o);$('#resultTitle').textContent=lastResult.results.length?'Небольшой план. Хороший день.':'Давайте чуть изменим планы';$('#countBadge').textContent=`${lastResult.results.length} из ${lastResult.candidates} мест`;$('#contextNote').textContent=`${o.minutes} минут · до ${o.radius} км · пешком · локальные объяснения${o.indoor?' · только помещения':''}${o.night?' · вечерний фильтр':''}. Часы и доступность могут измениться.`;if(/аэропорт|вылет|рейс/i.test(o.query))$('#contextNote').textContent+=' ВАЖНО: дорога в аэропорт и запас на регистрацию не рассчитаны. Не используйте этот бюджет как разрешение на прогулку перед рейсом.';$('#evidenceCount').textContent=`${dataset.pois.length} POI в базе`;$('#evidenceBody').innerHTML=`<p>Данные: ${esc(dataset.meta.source)} · получены ${esc((dataset.meta.fetchedAt||dataset.meta.collectedAt||'').slice(0,10))}. География и время — жёсткие ограничения; затем TF-IDF + словарь намерений + близость.</p><p>Исключено: по расстоянию ${lastResult.excluded.distance}, по времени ${lastResult.excluded.time}, категории ${lastResult.excluded.category}, доступности ${lastResult.excluded.accessibility}, контексту ${lastResult.excluded.context}.</p><p>Запрос: ${lastResult.queryTokens.map(t=>`<code>${esc(t)}</code>`).join(' ')}</p>${lastResult.results.map(p=>`<p><b>${esc(p.name)}</b>: оценка ${p.score}, текст ${p.lexical}; ${p.total} мин вместе с посещением.<br>Факт из источника: ${esc(p.description)}</p>`).join('')}<p>«Идея» — шаблонная рекомендация, не факт о программе места. Режим без LLM. Данные не гарантируют, что место открыто сейчас.</p>`;renderCards();drawMap();renderRoute();
 try{const status=await fetch('/api/status').then(r=>r.ok?r.json():null).catch(()=>null);if(status?.gemini&&version===searchVersion&&lastResult.results.length){$('#modeLabel').textContent='Gemini RAG доступен';const res=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:o.query,ids:lastResult.results.map(p=>p.id)})});if(res.ok&&version===searchVersion){const data=await res.json();if(data.text){const note=document.createElement('div');note.className='empty';const title=document.createElement('b');title.textContent='Совет Gemini · на основе найденных POI';const text=document.createElement('p');text.textContent=data.text;note.append(title,text);$('#results').prepend(note);$('#contextNote').textContent+=' Gemini RAG: ответ сформирован из найденных источников.';}}}}
 catch{if(version===searchVersion)$('#contextNote').textContent+=' AI недоступен: показан локальный ответ.';}}
$('#searchForm').onsubmit=e=>{e.preventDefault();search();};$('#minutes').oninput=()=>$('#minutesValue').textContent=`${$('#minutes').value} мин`;$('#location').onchange=()=>{origin=origins[$('#location').value]||origin;$('#geoStatus').textContent='';};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(c=>c.classList.toggle('selected',c===b));});
$('#geoBtn').onclick=()=>{if(!navigator.geolocation){$('#geoStatus').textContent='Геолокация не поддерживается. Выберите район.';return;}$('#geoStatus').textContent='Запрашиваем доступ к местоположению…';navigator.geolocation.getCurrentPosition(p=>{origin={lat:Math.round(p.coords.latitude*1000)/1000,lon:Math.round(p.coords.longitude*1000)/1000};let option=$('#location option[value="gps"]');if(!option){option=document.createElement('option');option.value='gps';option.textContent='Моё местоположение';$('#location').append(option);}$('#location').value='gps';$('#geoStatus').textContent='Координаты округлены до ~100 м и остаются в памяти вкладки.';search();},()=>$('#geoStatus').textContent='Доступ не получен. Выберите ближайший район вручную.',{enableHighAccuracy:false,timeout:10000,maximumAge:120000});};
document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{const s=b.dataset.scenario;$('#location').value=s==='expo'?'expo':s==='family'?'museum':'baiterek';origin=origins[$('#location').value];$('#minutes').value=s==='expo'?45:s==='family'?120:60;$('#minutes').oninput();$('#query').value=s==='expo'?'Хочу короткую прогулку и архитектуру рядом с EXPO':s==='family'?'Музей или интересное место с ребёнком':'Хочу кофе, тихое место и розетку';category=s==='family'?'museum':s==='coffee'?'cafe':'all';document.querySelectorAll('[data-cat]').forEach(c=>c.classList.toggle('selected',c.dataset.cat===category));$('#indoor').checked=false;$('#accessible').checked=false;$('#night').checked=false;search();});
$('#recenter').onclick=drawMap;$('#aboutBtn').onclick=$('#privacyBtn').onclick=()=>$('#about').showModal();$('#about .close').onclick=()=>$('#about').close();$('#about').onclick=e=>{if(e.target===$('#about'))$('#about').close();};
try{const response=await fetch('/data/pois.json');if(!response.ok)throw new Error('data');dataset=await response.json();$('#mapCount').textContent=`${dataset.pois.length} мест · данные OpenStreetMap`;$('#dataCredit').textContent=`© OpenStreetMap contributors · ODbL · ${dataset.pois.length} POI`;await search();}catch{$('#results').innerHTML='<div class="empty">Не удалось загрузить базу мест. Запустите приложение через <b>npm start</b> или обновите страницу. Открытие index.html как локального файла не поддерживается.</div>';$('#results').setAttribute('aria-busy','false');$('#countBadge').textContent='Нет данных';}
